from taf.hw.rf_attenuator.devices.jfw.jfw import JFW


class JFW50PA905(JFW):
    SET_PORT_COMMAND = "SMA {}"

    def _set_multiple_ports_decibel_attenuation(self, rf_port_addresses, attenuation_values_db):
        params_as_tuples = zip(rf_port_addresses, attenuation_values_db)
        params_as_string = ','.join(['{} {}'.format(port, value) for port, value in params_as_tuples])
        cmd = self.SET_PORT_COMMAND.format(params_as_string)
        self._write(cmd)
        return cmd

    def _prepare_set_command(self, attenuation_value, rf_port_address):
        return self.SET_PORT_COMMAND.format(rf_port_address + " " + str(attenuation_value)).strip(",")
